"use client";

import { motion, useMotionTemplate, useMotionValue, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** Where the lens sits over the content, as fractions from 0 to 1 of its width and height. */
export interface LensPoint {
  x: number;
  y: number;
}

/**
 * Props for a lens. `position` is `null` while the lens is hidden: pass it to
 * control the lens, or leave it out to let the pointer and the keyboard move it.
 */
export type LensProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** Names the area for screen readers, for example "Magnify the receipt". */
  label: string;
  /** Rendered twice, once at rest and once enlarged. Keep `id` attributes out of it. */
  children: ReactNode;
  position?: LensPoint | null;
  defaultPosition?: LensPoint | null;
  onPositionChange?: (position: LensPoint | null) => void;
  /** How many times larger the lens shows the content. */
  zoom?: number;
  /** The lens diameter in rem. */
  size?: number;
  /** Read out with the label, so a keyboard user learns the keys. */
  hint?: string;
  /** Classes for the enlarged copy's backdrop, when the content does not sit on `bg-background`. */
  lensClassName?: string;
};

// The lens is there on the next frame, because the person asked for it. Only its exit fades.
const SHOW: Transition = { duration: 0 };
const HIDE: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };
const CENTRE: LensPoint = { x: 0.5, y: 0.5 };
// One arrow press moves the lens this share of the content. Shift moves it five times as far.
const STEP = 0.02;
const ARROWS = {
  ArrowLeft: { x: -1, y: 0 },
  ArrowRight: { x: 1, y: 0 },
  ArrowUp: { x: 0, y: -1 },
  ArrowDown: { x: 0, y: 1 },
} satisfies Record<string, LensPoint>;

const isArrow = (key: string): key is keyof typeof ARROWS => Object.hasOwn(ARROWS, key);

const clamp = (value: number) => Math.min(Math.max(value, 0), 1);

/**
 * A round magnifier over any content. It follows the pointer exactly, with no
 * easing, because it stands in for the pointer. Focus the area and the arrow
 * keys move it. The enlarged copy is decoration: only the content itself is read out.
 */
export function Lens({
  label,
  children,
  position,
  defaultPosition = null,
  onPositionChange,
  zoom = 2,
  size = 7,
  hint = "Use the arrow keys to move the lens. Press Escape to hide it.",
  lensClassName,
  className,
  onPointerDown,
  onPointerMove,
  onPointerLeave,
  onFocus,
  onBlur,
  onKeyDown,
  ...rootProps
}: LensProps) {
  const start = position ?? defaultPosition ?? CENTRE;
  const [ownShown, setOwnShown] = useState(defaultPosition !== null);
  const shown = position === undefined ? ownShown : position !== null;
  // Where the lens is, or last was: it fades out there and the keyboard brings it back there.
  const last = useRef<LensPoint>(start);
  // The place lives in motion values, so a pointer move repaints the lens and never re-renders the content.
  const x = useMotionValue(start.x * 100);
  const y = useMotionValue(start.y * 100);
  const spot = useMotionTemplate`${x}% ${y}%`;
  const clip = useMotionTemplate`circle(${size / 2}rem at ${x}% ${y}%)`;
  const left = useMotionTemplate`${x}%`;
  const top = useMotionTemplate`${y}%`;
  const hintId = useId();
  // Focus that follows a press belongs to the pointer, which already places the lens.
  const pressed = useRef(false);
  const parked = useRef(false);

  const paint = (point: LensPoint) => {
    last.current = point;
    x.set(point.x * 100);
    y.set(point.y * 100);
  };

  // A controlled lens moves only when its owner says so.
  useLayoutEffect(() => {
    if (position) paint(position);
  });

  const move = (next: LensPoint | null) => {
    const current = shown ? last.current : null;
    if (next === current || (next && current && next.x === current.x && next.y === current.y)) return;
    if (position === undefined) {
      if (next) paint(next);
      setOwnShown(next !== null);
    }
    onPositionChange?.(next);
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event);
    parked.current = false;
    const box = event.currentTarget.getBoundingClientRect();
    if (box.width === 0 || box.height === 0) return;
    move({ x: clamp((event.clientX - box.left) / box.width), y: clamp((event.clientY - box.top) / box.height) });
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.target !== event.currentTarget) return;
    if (event.key === "Escape" && shown) {
      move(null);
      return;
    }
    if (!isArrow(event.key)) return;
    const arrow = ARROWS[event.key];
    // The arrows move the lens, so they must not scroll the page under it.
    event.preventDefault();
    parked.current = true;
    const stride = STEP * (event.shiftKey ? 5 : 1);
    move({ x: clamp(last.current.x + arrow.x * stride), y: clamp(last.current.y + arrow.y * stride) });
  };

  return (
    <div
      {...rootProps}
      role="group"
      aria-label={label}
      aria-describedby={hintId}
      tabIndex={0}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        pressed.current = true;
      }}
      onPointerMove={handlePointerMove}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        // A lens parked with the keyboard stays when the pointer drifts off.
        if (!parked.current) move(null);
      }}
      onFocus={(event) => {
        onFocus?.(event);
        if (event.target !== event.currentTarget || pressed.current) return;
        parked.current = true;
        move(last.current);
      }}
      onBlur={(event) => {
        onBlur?.(event);
        if (event.target !== event.currentTarget) return;
        pressed.current = false;
        parked.current = false;
        move(null);
      }}
      onKeyDown={handleKeyDown}
      className={cn(
        "relative rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        className,
      )}
    >
      {children}
      <span id={hintId} className="sr-only">
        {hint}
      </span>
      {/* The copy fills the same box as the content, so it lays out the same.
          It grows from the lens centre, and the clip keeps only the round part. */}
      <motion.div
        aria-hidden="true"
        inert
        initial={false}
        animate={{ opacity: shown ? 1 : 0 }}
        transition={shown ? SHOW : HIDE}
        style={{ clipPath: clip }}
        className={cn("pointer-events-none absolute inset-0 bg-background", lensClassName)}
      >
        <motion.div style={{ scale: zoom, transformOrigin: spot }} className="size-full">
          {children}
        </motion.div>
      </motion.div>
      <motion.div
        aria-hidden="true"
        data-lens-rim=""
        initial={false}
        animate={{ opacity: shown ? 1 : 0 }}
        transition={shown ? SHOW : HIDE}
        style={{ left, top, width: `${size}rem`, height: `${size}rem`, x: "-50%", y: "-50%" }}
        className="pointer-events-none absolute rounded-full border border-border shadow-lg ring-1 ring-foreground/10"
      />
    </div>
  );
}
